def _expand_braces(pattern):
    start = pattern.find("{")
    if start < 0:
        return [pattern]
    end = pattern.find("}", start)
    if end < 0:
        return [pattern]
    head = pattern[:start]
    alternatives = pattern[start + 1:end].split(",")
    tails = _expand_braces(pattern[end + 1:])
    return [head + alt + tail for alt in alternatives for tail in tails]


